import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import type { ReservationGroupState } from './action_conversation_render_projection'

const MIN_RESERVED_BLOCK_COUNT = 1

export interface ActionConversationReservationState {
    active: boolean
    conversationPath: string | null
    inputGroups: ReservationGroupState[]
    reservationSession: object | null
    sealedGroupKeys: string[]
    permanentKeys: Set<string>
    runningKeys: Set<string>
    slotCount: number
}

function runIsActive(status: PopupRunStatus) {
    return status === 'queued' || status === 'running' || status === 'waitingForInput'
}

/** Creates empty presentation state for chat-bottom reservation tracking. */
export function createActionConversationReservationState(): ActionConversationReservationState {
    return {
        active: false,
        conversationPath: null,
        inputGroups: [],
        permanentKeys: new Set(),
        reservationSession: null,
        runningKeys: new Set(),
        sealedGroupKeys: [],
        slotCount: 0,
    }
}

/** Advances reserved-slot state from visible render-group lifecycle changes. */
export function updateActionConversationReservation(
    previous: ActionConversationReservationState,
    conversationPath: string | null,
    groups: ReservationGroupState[],
    reservationSession: object,
    sealedGroupKeys: string[],
    status: PopupRunStatus,
) {
    const active = runIsActive(status)
    if (!active && !previous.active) return previous
    if (
        active === previous.active
        && conversationPath === previous.conversationPath
        && groups === previous.inputGroups
        && reservationSession === previous.reservationSession
        && sealedGroupKeys === previous.sealedGroupKeys
    ) return previous
    if (!active) return createActionConversationReservationState()

    const sessionChanged = !previous.active
        || previous.conversationPath !== conversationPath
        || previous.reservationSession !== reservationSession
    const retainedPermanentKeys = sessionChanged ? [] : previous.permanentKeys
    const runningKeys = new Set(groups.filter(({ running }) => running).map(({ key }) => key))
    const permanentKeys = new Set([
        ...retainedPermanentKeys,
        ...groups.filter(({ running }) => !running).map(({ key }) => key),
        ...sealedGroupKeys,
    ])
    if (sessionChanged) {
        return {
            active,
            conversationPath,
            inputGroups: groups,
            permanentKeys,
            reservationSession,
            runningKeys,
            sealedGroupKeys,
            slotCount: Math.max(MIN_RESERVED_BLOCK_COUNT, runningKeys.size),
        }
    }

    const newPermanentCount = [...permanentKeys].filter((key) => !previous.permanentKeys.has(key)).length
    const retainedRunningCount = [...runningKeys].filter((key) => previous.runningKeys.has(key)).length
    const newRunningCount = runningKeys.size - retainedRunningCount
    const reducedSlotCount = Math.max(MIN_RESERVED_BLOCK_COUNT, previous.slotCount - newPermanentCount)
    const availableSlotCount = Math.max(0, reducedSlotCount - retainedRunningCount)
    const slotCount = reducedSlotCount + Math.max(0, newRunningCount - availableSlotCount)

    return {
        active,
        conversationPath,
        inputGroups: groups,
        permanentKeys,
        reservationSession,
        runningKeys,
        sealedGroupKeys,
        slotCount,
    }
}

/** Returns currently unused slots rendered as bottom placeholders. */
export function reservedActionConversationBlockCount(state: ActionConversationReservationState) {
    return Math.max(0, state.slotCount - state.runningKeys.size)
}

import { Stack } from '@mui/material'
import { memo, useCallback, useLayoutEffect, useRef, useState, type UIEvent } from 'react'
import type { AgentConversation } from '../../../data/data_types'
import type { ActionConversationChange } from '../../../services/actions/action_run_registry'
import type { ActionQueuedPrompt } from '../../../data/action_run_types'
import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import { ActionConversationGroupList } from './action_conversation_group_list'
import { ActionConversationHistory } from './action_conversation_history'
import { ActionConversationRenderProjection } from './action_conversation_render_projection'
import {
    createActionConversationReservationState,
    reservedActionConversationBlockCount,
    updateActionConversationReservation,
} from './action_conversation_reservation'
import { ActionConversationReservedBlock } from './action_conversation_reserved_block'
import { ActionQueuedPromptRow } from './action_queued_prompt'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96

export type ConversationTranscript = Pick<AgentConversation, 'cardInternalId' | 'entries' | 'path' | 'providerSessions'> & {
    change?: ActionConversationChange
}

interface ActionConversationTranscriptProps {
    conversation: ConversationTranscript | null
    queuedPrompts?: ActionQueuedPrompt[]
    runId?: string | null
    status: PopupRunStatus
}

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

function runIsActive(status: PopupRunStatus) {
    return status === 'queued' || status === 'running' || status === 'waitingForInput'
}

/** Renders only transcript data, isolated from conversation metadata updates. */
export const ActionConversationTranscript = memo(function ActionConversationTranscript(
    { conversation, queuedPrompts = [], runId = null, status }: ActionConversationTranscriptProps,
) {
    const [projection] = useState(() => new ActionConversationRenderProjection())
    const projectionSnapshot = projection.update(conversation, runIsActive(status))
    const viewportRef = useRef<HTMLDivElement>(null)
    const viewportHeightRef = useRef<number | null>(null)
    const conversationPathRef = useRef<string | null | undefined>(undefined)
    const stuckToEndRef = useRef(true)
    const conversationPath = conversation?.path ?? null
    const [reservationState, setReservationState] = useState(() => updateActionConversationReservation(
        createActionConversationReservationState(),
        conversationPath,
        projectionSnapshot.reservationGroups,
        projectionSnapshot.reservationSession,
        projectionSnapshot.sealedGroupKeys,
        status,
    ))
    const nextReservationState = updateActionConversationReservation(
        reservationState,
        conversationPath,
        projectionSnapshot.reservationGroups,
        projectionSnapshot.reservationSession,
        projectionSnapshot.sealedGroupKeys,
        status,
    )
    if (nextReservationState !== reservationState) setReservationState(nextReservationState)
    const reservedBlockCount = reservedActionConversationBlockCount(nextReservationState)

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    const handleViewportResize = useCallback(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const previousViewportHeight = viewportHeightRef.current
        const viewportHeight = viewport.clientHeight
        viewportHeightRef.current = viewportHeight
        if (previousViewportHeight === viewportHeight || !stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    }, [])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const currentConversationPath = conversation?.path ?? null
        const conversationChanged = conversationPathRef.current !== currentConversationPath
        conversationPathRef.current = currentConversationPath
        if (conversationChanged) stuckToEndRef.current = true
        if (!stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    })

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        viewportHeightRef.current = viewport.clientHeight
        const resizeObserver = new ResizeObserver(handleViewportResize)
        resizeObserver.observe(viewport)

        return resizeObserver.disconnect.bind(resizeObserver)
    }, [handleViewportResize])

    return (
        <Stack aria-label="Conversation chat" onScroll={handleScroll} ref={viewportRef} spacing={1}
            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}>
            <ActionConversationHistory
                cardInternalId={conversation?.cardInternalId ?? null}
                groups={projectionSnapshot.historyGroups}
                projection={projection}
            />
            <ActionConversationGroupList
                cardInternalId={conversation?.cardInternalId ?? null}
                groups={projectionSnapshot.tailGroups}
                projection={projection}
            />
            {Array.from({ length: reservedBlockCount }, (_, index) => (
                <ActionConversationReservedBlock key={`reserved-block-${index}`} />
            ))}
            {runId ? queuedPrompts.map((entry) => (
                <ActionQueuedPromptRow entry={entry} key={entry.id} runId={runId} />
            )) : null}
        </Stack>
    )
})

import { Stack } from '@mui/material'
import { useEffect, useMemo, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { cardPopupService, subscribeCardPopups } from '../../../services/card_popup_service'
import { useBoundRunId, useRunSelector } from '../../hooks/use_action_runs'
import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import {
    ActionConversationTranscript,
} from './action_conversation_transcript'
import {
    createAcknowledgementConversationSelector,
    createConversationTranscriptSelector,
    selectedConversationTranscript,
} from './action_conversation_chat_selectors'
import { resolveDisplayedConversation, type ActionConversationStore } from './action_conversation_store'
import { ConversationMetaInfo } from './conversation_meta_info'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import type { ActionUsageValuesService } from '../run/popup/action_usage_values_service'

const EMPTY_QUEUED_PROMPTS: never[] = []

interface ActionConversationChatProps {
    actionId: string
    bindingStore: ActionRunBindingStore
    context: ActionContext
    popupEntryId?: string
    store: ActionConversationStore
    usageValuesService?: ActionUsageValuesService
}

/** Conversation surface; owns selection, live-run, visibility, and acknowledgement subscriptions. */
export function ActionConversationChat(
    { actionId, bindingStore, context, popupEntryId, store, usageValuesService }: ActionConversationChatProps,
) {
    const selectLiveTranscript = useMemo(() => createConversationTranscriptSelector(), [])
    const selectAcknowledgementConversation = useMemo(() => createAcknowledgementConversationSelector(), [])
    const boundRunId = useBoundRunId(bindingStore)
    const liveConversation = useRunSelector(boundRunId, selectAcknowledgementConversation)
    const liveTranscript = useRunSelector(boundRunId, selectLiveTranscript)
    const runStatus = useRunSelector(boundRunId, (run) => run?.status ?? 'idle')
    const runId = useRunSelector(boundRunId, (run) => run?.runId ?? null)
    const queuedPrompts = useRunSelector(boundRunId, (run) => run?.queuedPrompts ?? EMPTY_QUEUED_PROMPTS)
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const popupEntries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const selectedTranscript = useMemo(
        () => selectedConversationTranscript(selectedConversation),
        [selectedConversation],
    )
    const conversation = resolveDisplayedConversation(liveConversation, selectedConversation)
    const transcript = resolveDisplayedConversation(liveTranscript, selectedTranscript)
    const displayingLiveConversation = !selectedConversation || selectedConversation.path === liveConversation?.path
    const status: PopupRunStatus = displayingLiveConversation
        ? runStatus
        : conversation?.status === 'waitingForInput' ? 'waitingForInput' : 'idle'
    const cardInternalId = context.cardInternalId
    const visible = !!popupEntryId && popupEntries.at(-1)?.id === popupEntryId && !!cardInternalId && !!conversation

    useEffect(() => {
        if (!popupEntryId || !cardInternalId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, cardInternalId, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId, cardInternalId, actionId, conversation, false,
        )
    }, [actionId, cardInternalId, conversation, popupEntryId, visible])

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <ActionConversationTranscript
                conversation={transcript}
                queuedPrompts={displayingLiveConversation ? queuedPrompts : EMPTY_QUEUED_PROMPTS}
                runId={displayingLiveConversation ? runId : null}
                status={status}
            />
            <ConversationMetaInfo bindingStore={bindingStore} store={store} usageValuesService={usageValuesService} />
        </Stack>
    )
}

import type { AgentConversation } from '../../../data/data_types'
import type { ActionRun } from '../../../services/actions/action_run_registry'
import type { ConversationTranscript } from './action_conversation_transcript'

function transcriptConversation(conversation: AgentConversation): ConversationTranscript {
    const { cardInternalId, entries, path, providerSessions } = conversation

    return { cardInternalId, change: { kind: 'replace' }, entries, path, providerSessions }
}

/** Builds a selector whose result changes only when transcript fields change. */
export function createConversationTranscriptSelector() {
    let selectedConversation: AgentConversation | null = null
    let selectedChange: ActionRun['conversationChange'] = null
    let selectedTranscript: ConversationTranscript | null = null

    return (run: ActionRun | null) => {
        const conversation = run?.conversation ?? null
        const change = run?.conversationChange ?? null
        if (!conversation) {
            selectedConversation = null
            selectedChange = null
            selectedTranscript = null
            return null
        }
        const previousConversation = selectedConversation
        if (
            previousConversation !== null
            && previousConversation.cardInternalId === conversation.cardInternalId
            && previousConversation.entries === conversation.entries
            && previousConversation.path === conversation.path
            && previousConversation.providerSessions === conversation.providerSessions
            && selectedChange === change
        ) return selectedTranscript

        selectedConversation = conversation
        selectedChange = change
        selectedTranscript = { ...transcriptConversation(conversation), change: change ?? { kind: 'replace' } }
        return selectedTranscript
    }
}

/** Keeps acknowledgement data stable while unrelated conversation fields stream. */
export function createAcknowledgementConversationSelector() {
    let selectedConversation: AgentConversation | null = null

    return (run: ActionRun | null) => {
        const conversation = run?.conversation ?? null
        if (!conversation) {
            selectedConversation = null
            return null
        }
        const previousConversation = selectedConversation
        if (
            previousConversation !== null
            && previousConversation.id === conversation.id
            && previousConversation.path === conversation.path
            && previousConversation.viewed === conversation.viewed
        ) return selectedConversation

        selectedConversation = conversation
        return selectedConversation
    }
}

/** Produces transcript data for a loaded history selection. */
export function selectedConversationTranscript(conversation: AgentConversation | null) {
    return conversation ? transcriptConversation(conversation) : null
}

export async function finishActionRun(runId: string) {
    const bridge = getElectronActionBridge()
    if (!bridge?.finishActionRun) throw new Error('Finishing a streaming agent requires Electron')

    await bridge.finishActionRun(runId)
}

export async function notifyActionCardStateChange(cardInternalId: string | null, state: string) {
    if (!cardInternalId) return
    const bridge = getElectronActionBridge()
    if (!bridge?.notifyActionCardStateChange) throw new Error('Automatic agent finish requires Electron')

    await bridge.notifyActionCardStateChange(cardInternalId, state)
}

/** Stable state owner for one action run. */
export class ActionRunStore {
    private readonly listeners = new Set<StoreListener>()
    private readonly onReleased: (store: ActionRunStore) => void
    private snapshot: ActionRun

    constructor(snapshot: ActionRun, onReleased: (store: ActionRunStore) => void) {
        this.onReleased = onReleased
        this.snapshot = snapshot
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: StoreListener) => {
        this.listeners.add(listener)

        return () => {
            this.listeners.delete(listener)
            this.onReleased(this)
        }
    }

    hasConsumers() {
        return this.listeners.size > 0
    }

    update(snapshot: ActionRun) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

function actionContextKey(actionId: string, context: ActionContext) {
    return `${actionId}\u0000${contextKey(context)}`
}

function runEventType(runId: string) {
    return `run:${runId}`
}

function activeRun(run: ActionRun): ActiveActionRun {
    return { rootActionId: run.rootActionId, runId: run.runId, status: run.status }
}

function sameActiveRuns(first: ActiveActionRun[], second: ActiveActionRun[]) {
    return first.length === second.length && first.every(({ runId, status }, index) => (
        second[index]?.runId === runId && second[index]?.status === status
    ))
}

function conversationPickerMetadataChanged(previous: ActionRun['conversation'], current: ActionRun['conversation']) {
    return previous?.actionId !== current?.actionId
        || previous?.cardInternalId !== current?.cardInternalId
        || previous?.hasExplicitTitle !== current?.hasExplicitTitle
        || previous?.id !== current?.id
        || previous?.path !== current?.path
        || previous?.startedAt !== current?.startedAt
        || previous?.title !== current?.title
}

